import {VERSION,axes,questions,optionLabels,optionValues,score,validAnswers} from './model.mjs';
const key='persona-spectrum-v1';
const root=document.querySelector('#app');
const dialog=document.querySelector('#info-dialog');
let answers={},page=0,view='test',canStore=true,restored=false;
try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved?.version===VERSION){answers=validAnswers(saved.answers);page=Math.max(0,Math.min(9,Number.isInteger(saved.page)?saved.page:0));restored=Object.keys(answers).length>0;if(saved.view==='result'&&Object.keys(answers).length===60)view='result';}}catch{canStore=false;}
const count=()=>Object.keys(answers).length;
function persist(){try{localStorage.setItem(key,JSON.stringify({version:VERSION,answers,page,view}));}catch{canStore=false;}}
const icons={clock:'<circle cx="16" cy="16" r="11"/><path d="M16 9v7l5 3"/>',heart:'<path d="M16 26S3 18 3 10a7 7 0 0 1 13-3 7 7 0 0 1 13 3c0 8-13 16-13 16Z"/>',leaf:'<path d="M6 25C-1 6 20 4 27 5c1 16-10 24-21 20ZM7 25 23 9"/>'};
const icon=name=>`<svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]}</svg>`;
function hero(){return `<section class="hero"><span class="hero-shape shape-one"></span><span class="hero-shape shape-two"></span><p class="eyebrow">A LITTLE CURIOSITY. A DEEPER UNDERSTANDING.</p><h1>认识自己，从真实的回答开始。</h1><p class="intro">没有标准答案，也不需要成为任何人。<br><strong>跟随直觉，探索属于你的性格光谱。</strong></p><div class="hero-meta"><span><b>◷</b> 约 8–12 分钟</span><span><b>◇</b> 60 道原创题</span><span><b>⌁</b> 五个探索维度</span></div></section><section class="tips" aria-label="答题提示"><div class="tip">${icon('clock')}<div><strong>不必过度思考</strong><span class="tip-detail">选择平时的你，而不是理想中的你。</span></div></div><div class="tip">${icon('heart')}<div><strong>诚实面对自己</strong><span class="tip-detail">没有好坏之分，每种倾向都有价值。</span></div></div><div class="tip">${icon('leaf')}<div><strong>为变化留出空间</strong><span class="tip-detail">结果是一次观察，不是永远的标签。</span></div></div></section>`;}
function renderQuestion(q){return `<fieldset class="question ${Number.isInteger(answers[q.id])?'answered':''}" id="${q.id}"><legend id="${q.id}-label"><small>${String(q.number).padStart(2,'0')} / 60</small>${q.text}</legend><div class="choices"><span class="scale-end" aria-hidden="true">认同</span>${optionValues.map((value,i)=>`<label class="choice" style="--size:${[50,42,33,25,33,42,50][i]}px;--tone:${i<3?'#54a88f':i===3?'#a9a4ac':'#8863a3'}" title="${optionLabels[i]}"><input type="radio" name="${q.id}" value="${value}" aria-label="${optionLabels[i]}" ${answers[q.id]===value?'checked':''}><span aria-hidden="true"></span></label>`).join('')}<span class="scale-end" aria-hidden="true">不认同</span></div><div class="scale-mobile" aria-hidden="true"><span>认同</span><span>不认同</span></div></fieldset>`;}
function renderTest(){
 root.innerHTML=hero()+`${restored?`<div class="resume"><span>已恢复本机进度 · 已答 ${count()} / 60 题</span><button class="text-button" data-action="reset">重新开始</button></div>`:''}<section class="test-wrap" id="test" aria-label="人格探索测试"><div class="progress-area"><div class="progress-head"><strong>第 ${page+1} / 10 组</strong><span id="count-label">已完成 ${count()} / 60 题 · ${Math.round(count()/60*100)}%</span></div><div class="progress-track" role="progressbar" aria-label="答题进度" aria-valuemin="0" aria-valuemax="60" aria-valuenow="${count()}"><div class="progress-fill" style="width:${count()/60*100}%"></div></div></div><form id="quiz-form" novalidate>${questions.slice(page*6,page*6+6).map(renderQuestion).join('')}<div class="page-actions">${page>0?'<button type="button" class="secondary" data-action="previous">← 上一组</button>':''}<button class="primary" type="submit">${page===9?'查看我的结果':'下一组'}<span aria-hidden="true">→</span></button></div><div class="error" id="form-error" role="alert"></div></form><p class="page-note">${canStore?'进度仅保存在当前浏览器，你可以随时回来继续。':'浏览器存储不可用；关闭或刷新页面会丢失本次作答。'}<br>独立自我探索原型，非 16Personalities 或官方 MBTI 测评。<button class="text-button" data-action="method">了解评分方式</button></p></section>`;
 document.querySelector('#quiz-form').addEventListener('change',e=>{
  if(e.target.type!=='radio')return;answers[e.target.name]=Number(e.target.value);persist();
  const field=e.target.closest('fieldset');field.classList.add('answered');field.classList.remove('invalid');
  document.querySelector('#count-label').textContent=`已完成 ${count()} / 60 题 · ${Math.round(count()/60*100)}%`;
  document.querySelector('.progress-fill').style.width=count()/60*100+'%';document.querySelector('[role="progressbar"]').setAttribute('aria-valuenow',count());
  document.querySelector('#form-error').textContent='';
  const resumeText=document.querySelector('.resume span');if(resumeText)resumeText.textContent=`已恢复本机进度 · 已答 ${count()} / 60 题`;
 });
 document.querySelector('#quiz-form').addEventListener('submit',e=>{e.preventDefault();const missing=questions.slice(page*6,page*6+6).filter(q=>!Number.isInteger(answers[q.id]));if(missing.length){document.querySelector('#form-error').textContent=`还有 ${missing.length} 道题未选择，请完成后继续。`;missing.forEach(q=>document.getElementById(q.id).classList.add('invalid'));document.querySelector(`#${missing[0].id} input`).focus({preventScroll:true});document.getElementById(missing[0].id).scrollIntoView({block:'center',behavior:'smooth'});return;}if(page===9){view='result';persist();render();window.scrollTo({top:0,behavior:'smooth'});}else{page++;persist();renderTest();document.querySelector('#test').scrollIntoView({block:'start',behavior:'smooth'});}});
}
function insight(result){
 const [e,n,t,j]=result.dimensions;const hasX=result.code.includes('X');
 const lead=hasX?'你的倾向，保留了更多可能。':n.letter==='N'?(t.letter==='T'?'以想象打开可能，以逻辑找到方向。':'看见新的可能，也看见人的感受。'):(j.letter==='J'?'把眼前的事情，一件件做到扎实。':'在真实的体验中，找到自己的节奏。');
 const work=j.letter==='J'?'把目标、边界和截止时间说清楚，可能更容易让你进入状态。也可以刻意留一点缓冲，给新信息和变化空间。':j.letter==='P'?'保留选择和调整空间，可能更容易激发你的行动。面对长任务，可以尝试用小里程碑帮助自己及时收尾。':'这次作答没有显示明确的计划或灵活偏向。你可以比较独立任务和团队任务中的实际习惯。';
 const energy=e.letter==='E'?'你在交流一侧的得分更高。重要任务中，可以尝试通过讨论推进思考，同时给自己保留安静整理的时间。':e.letter==='I'?'你在独处一侧的得分更高。集中思考可能更适合你，也可以用小范围、提前准备的交流帮助想法被看见。':'外向与内向两侧得分相同。具体环境可能比一个固定标签更能解释你的能量变化。';
 return `<p class="eyebrow">YOUR PERSONAL SPECTRUM</p><div class="lead">${lead}</div><p>这是你本次作答的概括，不是能力排名。相同的倾向，也可以有完全不同的生活方式。</p><h3>你的能量节奏</h3><p>${energy}</p><h3>给工作中的你</h3><p>${work}</p>`;
}
function resultText(r){return `人格光谱 · 自我探索结果\n${r.code}\n\n${r.dimensions.map(d=>`${d.name}：${d.left} ${d.leftPercent}% / ${d.right} ${d.rightPercent}%${d.boundary?'（接近中点）':''}`).join('\n')}\n\n分数是本问卷内的线性换算，不是人口百分位、准确率或诊断。使用原创题库与等权计分，未经心理测量学验证，不等同于16Personalities或官方MBTI。\n版本：${VERSION}`;}
function renderResult(){
 const result=score(answers);
 root.innerHTML=`<section class="results"><div class="result-top"><span class="result-tag">你的本次性格光谱</span><h1>${result.code}</h1><p>比四个字母更重要的，是你如何理解自己。<br>从五个维度，看看你这次回答呈现的倾向。</p></div><div class="result-grid"><section class="dimension-panel" aria-labelledby="dimensions-title"><h2 id="dimensions-title" class="section-heading">你的五个维度</h2>${result.dimensions.map(d=>`<div class="dimension" style="--color:${d.color};--percent:${d.leftPercent}%"><h3>${d.name}<em>${d.boundary?'接近中点 · 不宜贴标签':'本次作答倾向'}</em></h3><div class="dimension-labels"><span>${d.left} <strong>${d.leftPercent}%</strong></span><span><strong>${d.rightPercent}%</strong> ${d.right}</span></div><div class="dimension-bar" role="img" aria-label="${d.name}：${d.left}${d.leftPercent}%，${d.right}${d.rightPercent}%"><span></span></div></div>`).join('')}<p class="formula-note">百分比为本问卷内的分数换算，不是人口百分位或结果准确率。X 表示两侧得分完全相同。</p></section><section class="insight-panel">${insight(result)}</section></div><div class="result-bottom">本结果使用原创题库与自行实现的等权评分，尚未经心理测量学验证。可用于自我观察，不应用来决定招聘、诊断或其他重要资格判断。靠近中点时，少量答案变化就可能改变字母，建议优先阅读维度而非类型名称。</div><div class="result-actions"><button class="primary" data-action="copy">复制结果 <span aria-hidden="true">↗</span></button><button class="secondary" data-action="download">下载报告</button><button class="secondary" data-action="print">打印 / 存为 PDF</button><button class="text-button" data-action="review">修改答案</button><button class="text-button" data-action="reset">重新测试</button></div><details class="readback"><summary>查看 60 道题的答案与计分明细</summary><ol>${questions.map(q=>`<li>${q.text}<span>${optionLabels[optionValues.indexOf(answers[q.id])]} · ${axes.find(a=>a.id===q.axis).name} · ${q.direction>0?'正向':'反向'} · 权重 ${q.weight} · 贡献 ${answers[q.id]*q.direction*q.weight}</span></li>`).join('')}</ol></details></section>`;
}
function render(){view==='result'?renderResult():renderTest();}
function openInfo(title,body){document.querySelector('#dialog-title').textContent=title;document.querySelector('#dialog-body').innerHTML=body;if(!dialog.open)dialog.showModal();}
function method(){openInfo('透明的题库与评分',`<p>这是一个参考分步人格测试交互的独立原型。60 道题均为原创，不是 16Personalities 的题库；下列公式也是自行实现，未取得原站专有权重。</p><h3>我们目前确认了什么？</h3><p>原站当前可见前 6 题采用七档选项，控件提交值从 −3 到 +3。提交值本身不能证明每题权重，也不能证明最终百分比如何生成。本原型与原站的答案编码方向不相同。</p><h3>本原型怎样计分？</h3><p>五个维度各 12 题，其中 6 道正向、6 道反向，权重均为 1。认同从 +3 递减到不认同 −3，反向题乘以 −1。</p><code>维度原始分 S = Σ（答案值 × 正反方向 × 权重）<br>最大绝对分 M = 3 × 12 = 36<br>左侧百分比 = round(50 + 50 × S / M)<br>右侧百分比 = 100 − 左侧百分比</code><p>原始分为 0 时用 X 表示未分出倾向，不强行分型。距离中点不超过 8 个百分点时显示提示；8 是产品提示阈值，并非统计置信区间。没有使用常模或诊断阈值。</p><h3>科学性与使用边界</h3><p>本问卷尚未完成信度、效度或中文常模验证。使用四字母缩写不代表它与 MBTI 或 NERIS 等效。严肃测评可基于公开量表另行开发、翻译和验证。</p><p><a href="https://www.16personalities.com/articles/our-theory" target="_blank" rel="noopener">16Personalities 官方框架 ↗</a>　<a href="https://ipip.ori.org/newScoringInstructions.htm" target="_blank" rel="noopener">IPIP 公开计分说明 ↗</a></p>${axes.map(a=>`<details><summary>${a.name} · ${a.left} / ${a.right}</summary><p>${a.hint}</p><ol>${questions.filter(q=>q.axis===a.id).map(q=>`<li>第 ${q.number} 题：${q.text}<br><small>${q.direction>0?'正向：认同增加左侧分':'反向：认同增加右侧分'} · 权重 1</small></li>`).join('')}</ol></details>`).join('')}`);}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3500);}
document.addEventListener('click',async e=>{
 const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;
 if(action==='close-dialog')dialog.close();
 if(action==='method')method();
 if(action==='privacy')openInfo('数据只留在你的浏览器',`<p>你的答题记录通过当前浏览器的本地存储保存，不会由本应用上传到服务器。不设置账户、不收集邮箱，也没有第三方分析脚本。</p><p>同一设备、同一浏览器中的其他使用者可能看到已保存的进度。你可以随时通过「清除本机答题记录」删除本应用保存的答案。</p><p>浏览器隐私模式或存储限制可能导致进度无法保存。站点托管服务仍可能处理常规访问日志；本应用不将答案放入网址。</p><button class="secondary" data-action="reset">清除本机答题记录</button>`);
 if(action==='previous'){page=Math.max(0,page-1);persist();renderTest();document.querySelector('#test').scrollIntoView({behavior:'smooth'});}
 if(action==='review'){view='test';page=0;persist();render();document.querySelector('#test').scrollIntoView({behavior:'smooth'});}
 if(action==='reset')openInfo('重新开始测试？',`<p>这会清除本浏览器已保存的 ${count()} 道答案与结果，回到第一组。</p><div class="page-actions"><button class="secondary" data-action="close-dialog">保留进度</button><button class="primary" data-action="confirm-reset">清除并重新开始</button></div>`);
 if(action==='confirm-reset'){answers={};page=0;view='test';restored=false;try{localStorage.removeItem(key);}catch{}dialog.close();render();window.scrollTo({top:0,behavior:'smooth'});}
 if(action==='copy'){const text=resultText(score(answers));try{await navigator.clipboard.writeText(text);toast('结果已复制');}catch{openInfo('复制你的结果','<p>浏览器未允许自动复制，请选择下方文字手动复制。</p><textarea id="copy-result" readonly style="width:100%;min-height:260px;padding:15px"></textarea>');document.querySelector('#copy-result').value=text;document.querySelector('#copy-result').select();}}
 if(action==='download'){const result=score(answers);const blob=new Blob([resultText(result)+'\n\n答题明细\n'+questions.map(q=>`${q.number}. ${q.text}\n${optionLabels[optionValues.indexOf(answers[q.id])]} | ${q.axis} | 方向 ${q.direction} | 权重 ${q.weight} | 贡献 ${answers[q.id]*q.direction}`).join('\n\n')],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`人格光谱-${result.code}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('报告已开始下载');}
 if(action==='print')window.print();
});
dialog.addEventListener('click',e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)dialog.close();}});
render();
